CREATE DATABASE IF NOT EXISTS philsurin CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE philsurin;

-- Existing users, varieties, validations, and grading_records are intentionally preserved.
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(50) NOT NULL DEFAULT 'viewer', active TINYINT(1) NOT NULL DEFAULT 1, email VARCHAR(190) NULL UNIQUE, full_name VARCHAR(150) NULL, status ENUM('ACTIVE','INACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE', last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS varieties (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS validations (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, variety_id INT NOT NULL, result ENUM('Validated','Needs review','Rejected') NOT NULL, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(variety_id) REFERENCES varieties(id));
CREATE TABLE IF NOT EXISTS grading_records (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, location_id VARCHAR(100) NOT NULL, project_location VARCHAR(150) NOT NULL, date_planted DATE NULL, dr_dp DATE NULL, control_name VARCHAR(100), grading_stage VARCHAR(30) NOT NULL, variety_id INT NOT NULL, location_size VARCHAR(50), grading_date DATE NOT NULL, replicate INT NOT NULL, germination DECIMAL(10,2) NULL, es_value DECIMAL(10,2) NULL, gs_value DECIMAL(10,2) NULL, remarks TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(variety_id) REFERENCES varieties(id), INDEX idx_grading_location(location_id));
CREATE TABLE IF NOT EXISTS roles (role_id INT AUTO_INCREMENT PRIMARY KEY, role_code VARCHAR(50) NOT NULL UNIQUE, role_name VARCHAR(100) NOT NULL, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id INT NOT NULL, role_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(role_id));
CREATE TABLE IF NOT EXISTS locations (location_id INT AUTO_INCREMENT PRIMARY KEY, location_code VARCHAR(100) NOT NULL UNIQUE, project_name VARCHAR(150) NOT NULL, farm_field_address VARCHAR(255), city_municipality VARCHAR(100), province VARCHAR(100), latitude DECIMAL(10,7), longitude DECIMAL(10,7), status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_locations (user_id INT NOT NULL, location_id INT NOT NULL, assigned_by INT NULL, assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id, location_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(location_id) REFERENCES locations(location_id), FOREIGN KEY(assigned_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS system_config (config_key VARCHAR(100) PRIMARY KEY, config_value TEXT, description VARCHAR(255), updated_by INT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS masterlist (masterlist_id BIGINT AUTO_INCREMENT PRIMARY KEY, record_id VARCHAR(100) NOT NULL UNIQUE, project_name VARCHAR(150) NOT NULL, location_id INT NULL, variety_id INT NULL, dr_number VARCHAR(100), date_gathered DATE, grading_35mar_date DATE, grading_4mar_date DATE, grading_6mar_date DATE, harvest_date DATE, status ENUM('DRAFT','ACTIVE','COMPLETED','ARCHIVED') NOT NULL DEFAULT 'DRAFT', remarks TEXT, created_by INT NULL, updated_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(location_id) REFERENCES locations(location_id), FOREIGN KEY(variety_id) REFERENCES varieties(id), FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(updated_by) REFERENCES users(id), INDEX idx_masterlist_status(status), INDEX idx_masterlist_location(location_id));
CREATE TABLE IF NOT EXISTS measurement_definitions (measurement_code VARCHAR(50) PRIMARY KEY, stage ENUM('01_GRADING','02_GRADING','03_GRADING','04_GRADING','HARVEST') NOT NULL, measurement_name VARCHAR(100) NOT NULL, data_type ENUM('NUMBER','TEXT') NOT NULL, required TINYINT(1) NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, display_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS validation_sessions (validation_id BIGINT AUTO_INCREMENT PRIMARY KEY, masterlist_id BIGINT NOT NULL, stage ENUM('01_GRADING','02_GRADING','03_GRADING','04_GRADING') NOT NULL, validation_date DATE NOT NULL, validator_id INT NOT NULL, status ENUM('DRAFT','SUBMITTED','VERIFIED','REJECTED') NOT NULL DEFAULT 'DRAFT', remarks TEXT, submitted_at DATETIME NULL, verified_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_validation(masterlist_id,stage,validation_date), FOREIGN KEY(masterlist_id) REFERENCES masterlist(masterlist_id), FOREIGN KEY(validator_id) REFERENCES users(id), INDEX idx_validation_status(status));
CREATE TABLE IF NOT EXISTS validation_measurements (measurement_id BIGINT AUTO_INCREMENT PRIMARY KEY, validation_id BIGINT NOT NULL, replicate_no TINYINT NOT NULL, measurement_code VARCHAR(50) NOT NULL, numeric_value DECIMAL(14,4) NULL, text_value TEXT NULL, encoded_value VARCHAR(100), remarks TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_measurement(validation_id,replicate_no,measurement_code), CHECK(replicate_no BETWEEN 1 AND 4), FOREIGN KEY(validation_id) REFERENCES validation_sessions(validation_id) ON DELETE CASCADE, FOREIGN KEY(measurement_code) REFERENCES measurement_definitions(measurement_code));
CREATE TABLE IF NOT EXISTS harvest_records (harvest_id BIGINT AUTO_INCREMENT PRIMARY KEY, masterlist_id BIGINT NOT NULL, harvest_date DATE NOT NULL, observation TEXT, encoded_observation VARCHAR(100), validator_id INT NOT NULL, status ENUM('DRAFT','SUBMITTED','VERIFIED','REJECTED') NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(masterlist_id) REFERENCES masterlist(masterlist_id), FOREIGN KEY(validator_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS c45_models (model_id BIGINT AUTO_INCREMENT PRIMARY KEY, model_code VARCHAR(100) NOT NULL, model_version VARCHAR(50) NOT NULL, model_status ENUM('TRAINING','ACTIVE','ARCHIVED') NOT NULL DEFAULT 'TRAINING', target_attribute VARCHAR(100) NOT NULL, training_record_count INT NOT NULL DEFAULT 0, accuracy DECIMAL(7,4) NULL, created_by INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, activated_at DATETIME NULL, archived_at DATETIME NULL, UNIQUE KEY uq_model_version(model_code,model_version), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS c45_training_runs (training_run_id BIGINT AUTO_INCREMENT PRIMARY KEY, model_id BIGINT NOT NULL, started_at DATETIME NOT NULL, completed_at DATETIME NULL, records_used INT NOT NULL DEFAULT 0, training_accuracy DECIMAL(7,4) NULL, validation_accuracy DECIMAL(7,4) NULL, status ENUM('RUNNING','COMPLETED','FAILED') NOT NULL DEFAULT 'RUNNING', error_message TEXT, initiated_by INT NOT NULL, FOREIGN KEY(model_id) REFERENCES c45_models(model_id), FOREIGN KEY(initiated_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS c45_training_records (training_run_id BIGINT NOT NULL, masterlist_id BIGINT NOT NULL, target_value VARCHAR(255) NOT NULL, included TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY(training_run_id,masterlist_id), FOREIGN KEY(training_run_id) REFERENCES c45_training_runs(training_run_id) ON DELETE CASCADE, FOREIGN KEY(masterlist_id) REFERENCES masterlist(masterlist_id));
CREATE TABLE IF NOT EXISTS c45_recommendations (recommendation_id BIGINT AUTO_INCREMENT PRIMARY KEY, masterlist_id BIGINT NOT NULL, model_id BIGINT NOT NULL, training_run_id BIGINT NULL, prediction VARCHAR(255) NOT NULL, confidence DECIMAL(7,4) NOT NULL, recommendation_status ENUM('NORMAL','INTERVENTION','REVIEW_REQUIRED') NOT NULL DEFAULT 'REVIEW_REQUIRED', explanation TEXT, generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_by INT NULL, reviewed_at DATETIME NULL, FOREIGN KEY(masterlist_id) REFERENCES masterlist(masterlist_id), FOREIGN KEY(model_id) REFERENCES c45_models(model_id), FOREIGN KEY(training_run_id) REFERENCES c45_training_runs(training_run_id), FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS c45_recommendation_factors (factor_id BIGINT AUTO_INCREMENT PRIMARY KEY, recommendation_id BIGINT NOT NULL, feature_name VARCHAR(100) NOT NULL, feature_value VARCHAR(255), encoded_value VARCHAR(100), decision_role VARCHAR(100), FOREIGN KEY(recommendation_id) REFERENCES c45_recommendations(recommendation_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (audit_id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80), entity_id VARCHAR(100), old_data JSON NULL, new_data JSON NULL, ip_address VARCHAR(45), user_agent VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit_created(created_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS dashboard_daily_metrics (metric_date DATE PRIMARY KEY, total_masterlist INT NOT NULL DEFAULT 0, validated_records INT NOT NULL DEFAULT 0, pending_records INT NOT NULL DEFAULT 0, recommendations INT NOT NULL DEFAULT 0, grading_01_completed INT NOT NULL DEFAULT 0, grading_02_completed INT NOT NULL DEFAULT 0, grading_03_completed INT NOT NULL DEFAULT 0, grading_04_completed INT NOT NULL DEFAULT 0, harvest_completed INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dashboard_monthly_metrics (`year_month` CHAR(7) PRIMARY KEY, total_records INT NOT NULL DEFAULT 0, validated_records INT NOT NULL DEFAULT 0, pending_records INT NOT NULL DEFAULT 0, recommendations INT NOT NULL DEFAULT 0, completion_percent DECIMAL(7,2) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
